// src/util/canonicalOrder.ts
function compareValues(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}
function canonicalEdgeOrder(edges) {
  const key = (e) => `${e.from}	${e.to}	${e.fromStrand ?? ""}${e.toStrand ?? ""}	${e.fromStrand ?? ""}`;
  return edges.map((e) => ({ e, k: key(e) })).sort((a, b) => compareValues(a.k, b.k)).map(({ e }) => e);
}
var chunksOf = (id) => (id.match(/\d+|\D+/g) ?? []).map(
  (chunk) => /^\d/.test(chunk) ? { numeral: true, text: chunk.replace(/^0+(?=\d)/, "") } : { numeral: false, text: chunk }
);
var compareChunks = (a, b) => a.numeral !== b.numeral ? a.numeral ? -1 : 1 : (a.numeral ? a.text.length - b.text.length : 0) || compareValues(a.text, b.text);
function compareChunkLists(x, y) {
  let order = 0;
  for (let i = 0; order === 0 && i < Math.min(x.length, y.length); i++) {
    const a = x[i];
    const b = y[i];
    order = a && b ? compareChunks(a, b) : 0;
  }
  return order || x.length - y.length;
}
var compareChunked = (a, b) => compareChunkLists(a.chunks, b.chunks) || compareValues(a.id, b.id);
var compareIds = (a, b) => compareChunked({ id: a, chunks: chunksOf(a) }, { id: b, chunks: chunksOf(b) });
function canonicalNodeOrder(nodes) {
  return nodes.map((n) => ({ n, id: n.id, chunks: chunksOf(n.id) })).sort(compareChunked).map(({ n }) => n);
}

export {
  compareValues,
  canonicalEdgeOrder,
  compareIds,
  canonicalNodeOrder
};
